/**
 * Průchod příležitosti od založení po uzavření. Stejné pořadí nabízí i přepínač
 * stavu na detailu, ať uživatel vidí všude tentýž číselník.
 */
export const STAVY_PRILEZITOSTI = [
  'Nová', 'Aktivní', 'Kontaktováno', 'Domluvená prohlídka', 'Nemá zájem', 'Uzavřeno',
] as const

export type StavPrilezitosti = typeof STAVY_PRILEZITOSTI[number]

/**
 * Barva stavu je v celé aplikaci stejná. Stavy, které něco sdělují, drží stavovou
 * variantu; kroky průchodu bez dobré/špatné konotace jedou na dekorativní paletě
 * z 1.6.33, ať se „Domluvená prohlídka“ nečte jako varování.
 *
 * Pozn.: stránka Tagu v design systému říká, že se dekorativní a stavové barvy
 * nemají míchat v jednom sloupci. Tady je to vědomé rozhodnutí zadavatele.
 */
export function stavPrilezitostiVariant(stav: string) {
  if (stav === 'Aktivní') return 'success' as const
  if (stav === 'Kontaktováno') return 'info' as const
  if (stav === 'Domluvená prohlídka') return 'purple' as const
  if (stav === 'Uzavřeno') return 'teal' as const
  if (stav === 'Nemá zájem') return 'danger' as const
  return 'neutral' as const
}

/**
 * Průchod prohlídky - od domluvení po zapsaný výsledek. Stejné hodnoty nabízí
 * modál „Zapsat výsledek“ i filtr Stav na seznamu příležitostí.
 */
export const STAVY_PROHLIDKY = [
  'Čeká na výsledek', 'Proběhla', 'Neuskutečnila se', 'Má zájem', 'Nemá zájem', 'Zrušena',
] as const

/**
 * Stav prohlídky drží stavové barvy - „Má zájem“ i „Nemá zájem“ nesou hodnotící
 * význam, takže dekorativní paleta by tu informaci zahodila. „Zrušena“ je
 * neutrální schválně: prohlídka se nekonala, takže o obchodu nic neříká.
 */
export function stavProhlidkyVariant(stav: string) {
  if (stav === 'Má zájem') return 'success' as const
  if (stav === 'Proběhla') return 'success' as const
  if (stav === 'Nemá zájem') return 'danger' as const
  if (stav === 'Čeká na výsledek') return 'warning' as const
  return 'neutral' as const
}

/**
 * Prodej / pronájem - kategorie, ne stav, proto dekorativní paleta. Stejný
 * číselník nese sloupec „Typ nabídky“ na příležitostech i „Typ poptávky“ na
 * poptávkách; barvu držíme všude stejnou, ať „Pronájem“ nemá na každé obrazovce
 * jinou.
 */
export function typObchoduVariant(typ: string) {
  if (typ === 'Prodej') return 'indigo' as const
  if (typ === 'Pronájem') return 'teal' as const
  return 'neutral' as const
}

/**
 * Typ nemovitosti stojí v tabulce hned vedle typu obchodu, takže má vlastní
 * část dekorativní palety - indigo a teal jsou rezervované pro typ obchodu,
 * jinak by se dva různé číselníky obarvily stejně. „Ostatní“ je zbytková
 * kategorie, tu nechává neutrální schválně.
 */
export function typNemovitostiVariant(typ: string) {
  switch (typ.toLowerCase()) {
    case 'byt':      return 'purple' as const
    case 'dům':      return 'lime' as const
    case 'pozemek':  return 'orange' as const
    case 'komerční': return 'pink' as const
    default:         return 'neutral' as const
  }
}

/**
 * V datech jsou druhy nemovitosti malým písmenem („byt“), protože se skládají do
 * názvů jako „Prodej bytu“. Samostatný štítek ale stojí jako popisek, a ten
 * začíná velkým písmenem - proto se velké písmeno přidává až při vykreslení,
 * nikdy se nepřepisují data.
 */
export function typNemovitostiLabel(typ: string) {
  return typ ? typ.charAt(0).toUpperCase() + typ.slice(1) : ''
}

